def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    my_D = 0
    opp_D = 0
    for me, opp in history:
        if me == 'D':
            my_D += 1
        if opp == 'D':
            opp_D += 1
    if opp_D == 0:
        if my_D == 0:
            if n == 3:
                return 'D'
            return 'C'
        else:
            if n >= 5:
                return 'D'
            return 'C'
    else:
        if opp_D > n * 0.4:
            return 'D'
        else:
            return 'C'
